INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'Should Teenagers Choose Their Own Clothes?', 'Many teenagers think they should be allowed to choose their own clothes. They say it is a way to show who they are. But some parents do not agree. They worry that teenagers may make poor choices. In some schools, students are not allowed to wear their own clothes. They must wear a uniform instead. Some students think this is unfair. They believe they are old enough to decide. Other students like uniforms because they are easy and cheap. There is no simple answer. Perhaps the best way is for parents and teenagers to talk and find a choice that works for both.', '议论文', 103, '[{"q": "What do many teenagers think?", "answer": "B", "options": ["They should wear uniforms.", "They should choose their own clothes.", "They should buy new clothes.", "They should not have clothes."], "explanation": "原文:should be allowed to choose their own clothes"}, {"q": "Why do some parents disagree?", "answer": "D", "options": ["Uniforms are nice.", "Clothes are expensive.", "They have no time.", "They worry teenagers may make poor choices."], "explanation": "原文:worry that teenagers may make poor choices"}, {"q": "What must students wear in some schools?", "answer": "B", "options": ["Old clothes.", "A uniform.", "No clothes.", "Their own clothes."], "explanation": "原文:must wear a uniform"}, {"q": "Why do some students like uniforms?", "answer": "D", "options": ["They are new.", "They are beautiful.", "They are warm.", "They are easy and cheap."], "explanation": "原文:easy and cheap"}, {"q": "What is the best way according to the writer?", "answer": "C", "options": ["Schools decide.", "Students decide alone.", "Parents and teenagers talk and find a choice.", "Parents decide alone."], "explanation": "原文:talk and find a choice that works for both"}]'::jsonb, '[{"word": "unfair", "cn": "不公平的"}, {"word": "uniform", "cn": "校服;制服"}, {"word": "choice", "cn": "选择"}]'::jsonb, 3, '9', 'U7');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'Liu Yu''s Dream', 'Liu Yu is a fifteen-year-old boy. He loves running and dreams of becoming a professional runner. He has trained hard since he was young. But his parents do not support his dream. They want him to study more and become a doctor. "Of course we want him to do well," says his mother. "But running is too risky." Liu Yu does not agree. He thinks he should be allowed to make his own decision. "If I am not allowed to follow my dream, I will regret it," he says. He hopes that one day his parents will understand and let him try.', '记叙文', 102, '[{"q": "How old is Liu Yu?", "answer": "D", "options": ["Sixteen.", "Thirteen.", "Eighteen.", "Fifteen."], "explanation": "原文:fifteen-year-old"}, {"q": "What is Liu Yu''s dream?", "answer": "B", "options": ["To be a singer.", "To become a professional runner.", "To be a doctor.", "To be a teacher."], "explanation": "原文:professional runner"}, {"q": "What do his parents want him to be?", "answer": "B", "options": ["An artist.", "A doctor.", "A runner.", "A teacher."], "explanation": "原文:become a doctor"}, {"q": "Why don''t his parents support him?", "answer": "A", "options": ["They think running is too risky.", "He has no time.", "He runs slowly.", "He is lazy."], "explanation": "原文:running is too risky"}, {"q": "What does Liu Yu think he should be allowed to do?", "answer": "A", "options": ["Make his own decision.", "Stop running.", "Study medicine.", "Leave home."], "explanation": "原文:allowed to make his own decision"}]'::jsonb, '[{"word": "professional", "cn": "职业的;专业的"}, {"word": "support", "cn": "支持"}, {"word": "regret", "cn": "懊悔;遗憾"}]'::jsonb, 3, '9', 'U7');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'Part-Time Jobs for Teenagers', 'In some countries, teenagers are allowed to have part-time jobs. They may work in shops or restaurants after school. Many people think this is a good idea. By working, teenagers can learn how to manage money and time. They also learn how to work with others. However, some parents do not agree. They worry that jobs will get in the way of study. They think school work should come first. Experts say part-time jobs can be helpful if teenagers do not work too many hours. The key is to find a good balance between study and work.', '说明文', 97, '[{"q": "What are teenagers allowed to do in some countries?", "answer": "B", "options": ["Smoke.", "Have part-time jobs.", "Drive cars.", "Stay out late."], "explanation": "原文:allowed to have part-time jobs"}, {"q": "What can teenagers learn by working?", "answer": "C", "options": ["How to swim.", "How to cook.", "How to manage money and time.", "How to drive."], "explanation": "原文:manage money and time"}, {"q": "Why do some parents disagree?", "answer": "B", "options": ["Jobs are unsafe.", "Jobs may get in the way of study.", "Jobs are far away.", "Jobs are boring."], "explanation": "原文:get in the way of study"}, {"q": "What do experts say?", "answer": "B", "options": ["Jobs are always bad.", "Part-time jobs can be helpful with limits.", "Teenagers must work.", "Study is useless."], "explanation": "原文:helpful if...not too many hours"}, {"q": "What is the key?", "answer": "C", "options": ["Study less.", "Quit school.", "Find a good balance between study and work.", "Work more."], "explanation": "原文:find a good balance"}]'::jsonb, '[{"word": "manage", "cn": "管理;应付"}, {"word": "balance", "cn": "平衡"}, {"word": "expert", "cn": "专家"}]'::jsonb, 3, '9', 'U7');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'Mom Knows Best', 'When I was a small child, my mom held my hand when we crossed the road. When I was tired, she carried me. I thought she was too strict. When I was a teenager, I wanted to eat ice cream every day. But she said no. I was not allowed to stay up late or watch too much TV. I thought she did not understand me. Now I am older. I look back at those times. I know now that my mom always wanted the best for me. She was not being unkind. She was keeping me safe. Mom really does know best.', '记叙文', 103, '[{"q": "What did mom do when crossing the road?", "answer": "A", "options": ["She held the child''s hand.", "She walked ahead.", "She carried the child.", "She said no."], "explanation": "原文:held my hand when we crossed"}, {"q": "What did the child want as a teenager?", "answer": "D", "options": ["To study more.", "To sleep early.", "To stay home.", "To eat ice cream every day."], "explanation": "原文:eat ice cream every day"}, {"q": "What was the child not allowed to do?", "answer": "A", "options": ["Stay up late or watch too much TV.", "Eat dinner.", "Go to school.", "Read books."], "explanation": "原文:not allowed to stay up late or watch too much TV"}, {"q": "What does the writer understand now?", "answer": "C", "options": ["Mom was unkind.", "Mom was lazy.", "Mom always wanted the best.", "Mom was wrong."], "explanation": "原文:always wanted the best for me"}, {"q": "What is the main idea?", "answer": "C", "options": ["Ice cream is bad.", "TV is fun.", "Mom knows best.", "Roads are dangerous."], "explanation": "主旨:Mom Knows Best"}]'::jsonb, '[{"word": "strict", "cn": "严格的"}, {"word": "teenager", "cn": "青少年"}, {"word": "safe", "cn": "安全的"}]'::jsonb, 3, '9', 'U7');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'Are School Uniforms a Good Idea?', 'School uniforms are a hot topic. Should students be allowed to wear what they like, or should they wear uniforms? Those who like uniforms say they make students equal. No one is judged by their clothes. Uniforms also save time in the morning. But others think uniforms are boring. They believe students should be allowed to show their own style. Some say uniforms stop students from being creative. In many schools, students are not allowed to change their uniforms at all. Maybe schools could let students help design the uniforms. That way, both sides might be happy.', '议论文', 97, '[{"q": "What is the hot topic?", "answer": "C", "options": ["What to eat.", "How to drive.", "Whether students should wear uniforms.", "Where to study."], "explanation": "原文:School uniforms are a hot topic"}, {"q": "Why do some people like uniforms?", "answer": "D", "options": ["They are warm.", "They are colorful.", "They are cheap only.", "They make students equal."], "explanation": "原文:make students equal"}, {"q": "What do others think about uniforms?", "answer": "D", "options": ["They are safe.", "They are nice.", "They are cheap.", "They are boring."], "explanation": "原文:uniforms are boring"}, {"q": "What do some say uniforms stop?", "answer": "C", "options": ["Students from eating.", "Students from sleeping.", "Students from being creative.", "Students from learning."], "explanation": "原文:stop students from being creative"}, {"q": "What does the writer suggest?", "answer": "A", "options": ["Let students help design the uniforms.", "Sell uniforms.", "Ban uniforms.", "Force uniforms."], "explanation": "原文:let students help design"}]'::jsonb, '[{"word": "equal", "cn": "平等的"}, {"word": "judge", "cn": "评判"}, {"word": "creative", "cn": "有创意的"}]'::jsonb, 3, '9', 'U7');
INSERT INTO public.junior_reading (id, grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (gen_random_uuid(), 9, 'School Rules Notice', 'GREENWOOD SCHOOL — STUDENT RULES. Please read these rules carefully. IN CLASS: Students are not allowed to use mobile phones. Phones must be turned off. CLOTHES: Students should wear the school uniform every day. On sports day, students are allowed to wear sports clothes. LIBRARY: Students must be quiet. Eating and drinking are not allowed. SAFETY: Students are not allowed to leave school during the day without a note from a parent. CLUBS: All students are allowed to join one club after school. We hope these rules help everyone study and stay safe. Thank you for following them.', '应用文', 98, '[{"q": "What are students not allowed to use in class?", "answer": "A", "options": ["Mobile phones.", "Books.", "Computers.", "Pens."], "explanation": "原文:not allowed to use mobile phones"}, {"q": "When can students wear sports clothes?", "answer": "A", "options": ["On sports day.", "On Monday.", "Never.", "Every day."], "explanation": "原文:on sports day...allowed to wear sports clothes"}, {"q": "What is not allowed in the library?", "answer": "C", "options": ["Talking quietly.", "Reading.", "Eating and drinking.", "Studying."], "explanation": "原文:Eating and drinking are not allowed"}, {"q": "What do students need to leave school during the day?", "answer": "D", "options": ["A phone.", "A ticket.", "A book.", "A note from a parent."], "explanation": "原文:without a note from a parent"}, {"q": "How many clubs can a student join?", "answer": "A", "options": ["One.", "Two.", "Three.", "None."], "explanation": "原文:join one club"}]'::jsonb, '[{"word": "rule", "cn": "规则"}, {"word": "safety", "cn": "安全"}, {"word": "quiet", "cn": "安静的"}]'::jsonb, 3, '9', 'U7');
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U7', 'My Own Decisions', 'Like many teenagers, I want to be (1)____ to make my own decisions. My parents are very (2)____. They decide what time I go to bed and what clothes I (3)____. I know they (4)____ about me. But I think I am old (5)____ to make some choices myself. For example, I should be (6)____ to choose my own hobbies. Last week, I (7)____ my mom that I wanted to join the art club. At first she said (8)____. But after we (9)____ about it, she agreed. Now I am very (10)____. Talking with parents really helps.', 97, 3, '[{"q": "1", "answer": "D", "options": ["allows", "allowing", "allow", "allowed"], "explanation": "被允许 be allowed"}, {"q": "2", "answer": "A", "options": ["strict", "happy", "kind", "free"], "explanation": "严格的 strict"}, {"q": "3", "answer": "A", "options": ["wear", "read", "drive", "eat"], "explanation": "穿 wear"}, {"q": "4", "answer": "B", "options": ["sell", "worry", "leave", "forget"], "explanation": "担心 worry about"}, {"q": "5", "answer": "C", "options": ["so", "too", "enough", "very"], "explanation": "足够大 old enough"}, {"q": "6", "answer": "D", "options": ["made", "told", "stopped", "allowed"], "explanation": "被允许 allowed to"}, {"q": "7", "answer": "A", "options": ["told", "spoke", "asked", "said"], "explanation": "告诉 told sb"}, {"q": "8", "answer": "C", "options": ["yes", "ok", "no", "sure"], "explanation": "说不 said no"}, {"q": "9", "answer": "B", "options": ["cried", "talked", "fought", "slept"], "explanation": "谈过 talked about"}, {"q": "10", "answer": "B", "options": ["tired", "happy", "angry", "sad"], "explanation": "开心 happy"}]'::jsonb, 1);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U7', 'School Rules', 'Every school has rules, and students must (1)____ them. At our school, we are not (2)____ to use phones in class. Phones must be turned (3)____ during lessons. We are also not allowed to (4)____ the school during the day without a note. Some students think the rules are too (5)____. But I think most rules are (6)____ for us. For example, the rule about phones helps us (7)____ on our studies. The rule about safety keeps us (8)____. Of course, students should be (9)____ to share their ideas about the rules. Good rules make school a (10)____ place to learn.', 101, 3, '[{"q": "1", "answer": "B", "options": ["break", "follow", "forget", "lose"], "explanation": "遵守 follow rules"}, {"q": "2", "answer": "A", "options": ["allowed", "stopped", "made", "kept"], "explanation": "被允许 allowed"}, {"q": "3", "answer": "C", "options": ["down", "on", "off", "up"], "explanation": "关掉 turned off"}, {"q": "4", "answer": "A", "options": ["leave", "clean", "build", "enter"], "explanation": "离开 leave"}, {"q": "5", "answer": "B", "options": ["free", "strict", "easy", "kind"], "explanation": "严格 strict"}, {"q": "6", "answer": "C", "options": ["bad", "sad", "good", "hard"], "explanation": "有益 good for"}, {"q": "7", "answer": "B", "options": ["run", "focus", "play", "sleep"], "explanation": "专注 focus on"}, {"q": "8", "answer": "A", "options": ["safe", "late", "tired", "busy"], "explanation": "安全 keep safe"}, {"q": "9", "answer": "D", "options": ["made", "told", "stopped", "allowed"], "explanation": "被允许 allowed to"}, {"q": "10", "answer": "D", "options": ["colder", "smaller", "worse", "better"], "explanation": "更好 better place"}]'::jsonb, 2);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U7', 'A Talk with My Dad', 'Last weekend, I had a long (1)____ with my dad. I told him I wanted to be (2)____ to choose my own subjects. He listened (3)____ to me. At first, he did not (4)____. He said I was too young to decide. But I explained why it was (5)____ to me. I said I should be (6)____ to follow my own interests. My dad thought for a while. Then he (7)____ that maybe I had a point. He agreed to (8)____ me choose two subjects. I was so (9)____! This talk taught me that if you want something, you should (10)____ talk to your parents about it.', 107, 3, '[{"q": "1", "answer": "B", "options": ["color", "talk", "price", "game"], "explanation": "谈话 talk"}, {"q": "2", "answer": "B", "options": ["kept", "allowed", "made", "stopped"], "explanation": "被允许 allowed"}, {"q": "3", "answer": "C", "options": ["sadly", "loudly", "carefully", "quickly"], "explanation": "认真地 carefully"}, {"q": "4", "answer": "A", "options": ["agree", "disagree", "leave", "sleep"], "explanation": "同意 agree"}, {"q": "5", "answer": "D", "options": ["cheap", "boring", "easy", "important"], "explanation": "重要 important"}, {"q": "6", "answer": "A", "options": ["allowed", "made", "stopped", "told"], "explanation": "被允许 allowed to"}, {"q": "7", "answer": "A", "options": ["said", "ran", "asked", "cried"], "explanation": "说 said"}, {"q": "8", "answer": "D", "options": ["make", "keep", "stop", "let"], "explanation": "让 let sb do"}, {"q": "9", "answer": "C", "options": ["angry", "tired", "happy", "sad"], "explanation": "开心 happy"}, {"q": "10", "answer": "B", "options": ["badly", "calmly", "seldom", "never"], "explanation": "冷静地 calmly talk"}]'::jsonb, 3);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U7', 'Growing Up', 'When I was young, I was not (1)____ to do many things. I could not cross the road (2)____. My mom always held my (3)____. I thought she was too (4)____. But now I understand she was keeping me (5)____. As I grew older, I was allowed to do (6)____ things by myself. Now I can go to school (7)____. I can also make some of my own (8)____. Growing up means getting more (9)____, but it also means more responsibility. I am thankful to my parents for (10)____ me grow up step by step.', 95, 3, '[{"q": "1", "answer": "A", "options": ["allowed", "allowing", "allows", "allow"], "explanation": "被允许 allowed"}, {"q": "2", "answer": "D", "options": ["together", "late", "early", "alone"], "explanation": "独自 alone"}, {"q": "3", "answer": "C", "options": ["book", "head", "hand", "foot"], "explanation": "手 hand"}, {"q": "4", "answer": "D", "options": ["free", "happy", "kind", "strict"], "explanation": "严格 strict"}, {"q": "5", "answer": "B", "options": ["busy", "safe", "late", "sad"], "explanation": "安全 safe"}, {"q": "6", "answer": "B", "options": ["less", "more", "worse", "fewer"], "explanation": "更多 more things"}, {"q": "7", "answer": "C", "options": ["slowly", "together", "alone", "late"], "explanation": "独自 alone"}, {"q": "8", "answer": "B", "options": ["games", "decisions", "prices", "colors"], "explanation": "决定 decisions"}, {"q": "9", "answer": "A", "options": ["freedom", "time", "food", "money"], "explanation": "自由 freedom"}, {"q": "10", "answer": "A", "options": ["helping", "losing", "leaving", "stopping"], "explanation": "帮助 helping me"}]'::jsonb, 4);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U7', 'Part-Time Work', 'In some places, teenagers are (1)____ to do part-time jobs. They may work in a shop or a (2)____ after school. Many people think this is a good (3)____. By working, young people learn how to (4)____ their time and money. They also learn how to (5)____ with others. But some parents do not (6)____. They are afraid that work will get in the (7)____ of study. They think school should come (8)____. Experts say a part-time job is fine if it is not (9)____ many hours. The key is to find a good (10)____ between work and study.', 99, 3, '[{"q": "1", "answer": "D", "options": ["allow", "allows", "allowing", "allowed"], "explanation": "被允许 allowed"}, {"q": "2", "answer": "A", "options": ["restaurant", "price", "color", "game"], "explanation": "餐馆 restaurant"}, {"q": "3", "answer": "B", "options": ["price", "idea", "song", "color"], "explanation": "主意 idea"}, {"q": "4", "answer": "D", "options": ["break", "throw", "lose", "manage"], "explanation": "管理 manage"}, {"q": "5", "answer": "A", "options": ["work", "run", "play", "sleep"], "explanation": "合作 work with"}, {"q": "6", "answer": "A", "options": ["agree", "disagree", "cry", "leave"], "explanation": "同意 agree"}, {"q": "7", "answer": "C", "options": ["road", "window", "way", "door"], "explanation": "妨碍 in the way of"}, {"q": "8", "answer": "B", "options": ["last", "first", "slow", "late"], "explanation": "第一 come first"}, {"q": "9", "answer": "B", "options": ["very", "too", "much", "so"], "explanation": "太多 too many"}, {"q": "10", "answer": "C", "options": ["color", "price", "balance", "game"], "explanation": "平衡 balance"}]'::jsonb, 5);
INSERT INTO public.junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (gen_random_uuid(), 9, '9', 'U7', 'Different Opinions', 'People often have (1)____ opinions about what teenagers should be allowed to do. Some adults (2)____ that teenagers are too young to make big choices. They think young people should always (3)____ to their parents. Other people (4)____ with this. They believe teenagers should be (5)____ to make some of their own decisions. They say that making choices helps young people (6)____ up. Of course, some choices are (7)____ for teenagers to make alone. In these cases, parents and children should (8)____ together. The best way is to (9)____ to each other with respect. Then they can find an answer that (10)____ everyone.', 103, 3, '[{"q": "1", "answer": "C", "options": ["empty", "same", "different", "quiet"], "explanation": "不同 different"}, {"q": "2", "answer": "A", "options": ["think", "thought", "thinking", "thinks"], "explanation": "认为 think"}, {"q": "3", "answer": "B", "options": ["sleep", "listen", "run", "talk"], "explanation": "听从 listen to"}, {"q": "4", "answer": "D", "options": ["cry", "agree", "leave", "disagree"], "explanation": "不同意 disagree"}, {"q": "5", "answer": "B", "options": ["kept", "allowed", "stopped", "made"], "explanation": "被允许 allowed"}, {"q": "6", "answer": "B", "options": ["lose", "grow", "throw", "break"], "explanation": "成长 grow up"}, {"q": "7", "answer": "A", "options": ["hard", "easy", "free", "cheap"], "explanation": "难 hard"}, {"q": "8", "answer": "D", "options": ["fight", "run", "sleep", "talk"], "explanation": "商量 talk together"}, {"q": "9", "answer": "A", "options": ["listen", "cry", "leave", "shout"], "explanation": "倾听 listen"}, {"q": "10", "answer": "C", "options": ["throws", "breaks", "suits", "loses"], "explanation": "适合 suits everyone"}]'::jsonb, 6);
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U7 听力·对话 Choosing Clothes', '九年级 Unit7 听力·青少年话题/be allowed to', 2, 'W: Do you think teenagers should be allowed to choose their own clothes?
