INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U7 听力·对话 Part-Time Job', '九年级 Unit7 听力·青少年话题/be allowed to', 2, 'W: My parents said I can have a part-time job this summer.
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U7 听力·短文 Mom Knows Best', '九年级 Unit7 听力·青少年话题/be allowed to', 2, 'When I was little, my mom held my hand on the road.
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U7 听力·对话 At the Museum', '九年级 Unit7 听力·青少年话题/be allowed to', 2, 'W: Excuse me, are we allowed to take photos here?
INSERT INTO public.junior_listening_exercises (id, grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (gen_random_uuid(), 9, '九年级 U7 听力·短文 School Rules', '九年级 Unit7 听力·青少年话题/be allowed to', 2, 'Our school has some important rules.
INSERT INTO public.junior_writing_prompts (id, grade, topic, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, difficulty, title_en, high_sentences, error_pairs, paragraph_template, volume, unit) SELECT gen_random_uuid(), 9, 'Should Teenagers Be Allowed to ...?', '就一个与青少年相关的话题写一篇短文,表达你的观点(如:青少年是否应被允许做兼职/选择自己的衣服/自己做决定)。用should be allowed to表达观点,说明理由。60词左右。', 'Write a short passage on the topic: "Should Teenagers Be Allowed to ...?".', '["你讨论的话题是什么", "你的观点(should/should not be allowed to)", "至少两条理由", "结尾总结你的看法"]'::jsonb, 70, 100, 'I think teenagers should be allowed to make their own decisions. One reason is that making choices helps young people grow up. They learn from both good and bad choices. Another reason is that teenagers are old enough to know what they want. Of course, some big decisions should be made with parents. But in daily life, teenagers should be allowed to choose for themselves. This helps them become more responsible.', 'content:含话题/观点/两条理由/总结(4分)；language:正确使用should be allowed to及观点表达(3分)；structure:论点清晰、衔接得当(2分)；wordcount:词数达标、书写规范(1分)', 3, 'Should Teenagers Be Allowed to ...?', '["should (not) be allowed to ...", "I think / I don''t think ...", "One reason is ...", "Another reason is ...", "In my opinion ...", "too young to ...", "old enough to ..."]'::jsonb, '[]'::jsonb, '要点:你讨论的话题是什么；你的观点(should/should not be allowed to)；至少两条理由；结尾总结你的看法', '9', 'U7' WHERE NOT EXISTS (SELECT 1 FROM public.junior_writing_prompts WHERE volume='9' AND unit='U7' AND topic='Should Teenagers Be Allowed to ...?');
